const labSlug = value => value.toLowerCase().replace(/[^a-z0-9_-]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || 'lab';
const validHost = value => {
  if (!value || value.length > 253) return false;
  if (/^[0-9.]+$/.test(value)) return value.split('.').length === 4 && value.split('.').every(x => /^\d{1,3}$/.test(x) && +x <= 255);
  return value.split('.').every(x => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i.test(x));
};
const fieldError = (key, value) => {
  if (!value.trim()) return 'Required for this command';
  if (/[\x00-\x1f\x7f]/.test(value)) return 'Use a single line without control characters';
  if (key === 'name') return value.length <= 100 ? '' : 'Use 100 characters or fewer';
  if (key === 'username') return /^[a-z0-9_.@$-]{1,100}$/i.test(value) ? '' : 'Enter the username only, without the domain or spaces';
  if (key === 'dcIp') return /^[0-9.]+$/.test(value) && validHost(value) ? '' : 'Enter a valid IPv4 address';
  if (!validHost(value)) return 'Enter a hostname or IPv4 address using letters, numbers, dots, and hyphens';
  if (['domain', 'dcHost'].includes(key) && (!value.includes('.') || /^[0-9.]+$/.test(value))) return 'Enter a full DNS name, such as example.local';
  return '';
};
const renderLabCommand = (code, values) => {
  const required = new Set();
  const dependencies = {folder: ['name'], identity: ['domain', 'username'], principal: ['username', 'domain']};
  const rendered = code.replace(/\{\{(\w+)\}\}/g, (token, key) => {
    const keys = dependencies[key] || [key];
    keys.forEach(k => required.add(k));
    if (keys.some(k => fieldError(k, values[k] || ''))) return token;
    if (key === 'folder') return labSlug(values.name);
    if (key === 'identity') return shellQuote(values.domain + '\\' + values.username);
    if (key === 'principal') return cypherQuote((values.username + '@' + values.domain).toUpperCase());
    // Validated DNS and IP values are safe unquoted; usernames are shell-quoted.
    return key === 'username' ? shellQuote(values[key]) : values[key];
  });
  return {code: rendered, missing: [...required].filter(k => fieldError(k, values[k] || ''))};
};
const newLab = (id, first) => ({id, values: Object.fromEntries(labFields.map(([key]) => [key, ''])), profile: 'none', current: first, checks: {}, notes: {}});
const readLabStore = (raw, data) => {
  const state = JSON.parse(raw);
  const ids = new Set(data.workflows.map(w => w.id));
  if (state?.version !== 1 || !Array.isArray(state.labs) || !state.labs.length || typeof state.active !== 'string') throw Error('Unrecognized saved lab format');
  const unique = new Set();
  for (const lab of state.labs) {
    if (!lab || typeof lab.id !== 'string' || unique.has(lab.id) || !ids.has(lab.current) || !data.profiles.some(p => p.id === lab.profile)) throw Error('Invalid saved lab');
    unique.add(lab.id);
    if (!lab.values || labFields.some(([key]) => typeof lab.values[key] !== 'string')) throw Error('Invalid lab values');
    if (!lab.notes || !lab.checks || typeof lab.notes !== 'object' || typeof lab.checks !== 'object') throw Error('Invalid lab notes');
    for (const w of data.workflows) {
      if (lab.notes[w.id] !== undefined && typeof lab.notes[w.id] !== 'string') throw Error('Invalid note');
      if (lab.checks[w.id] !== undefined && (!Array.isArray(lab.checks[w.id]) || lab.checks[w.id].length > w.checks.length || lab.checks[w.id].some(x => typeof x !== 'boolean'))) throw Error('Invalid checklist');
    }
  }
  if (!unique.has(state.active)) throw Error('Missing active lab');
  return state;
};
const exportLabMarkdown = (lab, data) => {
  const fence = text => '`'.repeat(Math.max(3, ...((text.match(/`+/g) || []).map(x => x.length + 1))));
  const noteBlock = text => {const f = fence(text); return f + 'text\n' + text + '\n' + f;};
  const lines = ['# ' + (lab.values.name || 'Untitled lab').replace(/[\r\n]/g, ' '), '', '[Open the lab guide](https://dashboard-aed21664.mintlify.site/lab-guide)', '', '## Lab context', ''];
  for (const [key, label] of labFields) lines.push('- ' + label + ': ' + (lab.values[key] || '(not set)').replace(/[\r\n]/g, ' '));
  lines.push('', 'Current workflow: ' + data.workflows.find(w => w.id === lab.current).title, '', 'These are prepared command examples, not a record of executed commands. Checkboxes and notes are your recorded observations.');
  for (const [i, w] of data.workflows.entries()) {
    lines.push('', '## ' + (i + 1) + '. ' + w.title, '', w.goal, '');
    w.checks.forEach((check, j) => lines.push('- [' + (lab.checks[w.id]?.[j] ? 'x' : ' ') + '] ' + check));
    if (lab.notes[w.id]) lines.push('', '### My findings', '', noteBlock(lab.notes[w.id]));
    for (const c of w.commands) {const rendered = renderLabCommand(c.code, lab.values); lines.push('', c.label + (rendered.missing.length ? ' (fill placeholders before use)' : ''), '', '```' + c.language, rendered.code, '```');}
    lines.push('', ...w.links.map(l => '- [' + l.label + '](' + (l.href.startsWith('/') ? 'https://dashboard-aed21664.mintlify.site' : '') + l.href + ')'));
  }
  return lines.join('\n') + '\n';
};

// Additive fields on the established lab-guide store. Old labs remain valid.
const studyKey = 'cpts-lab-guide-v1';
const studyId = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 10);
const studyNotebook = lab => ({boxId:'',services:'',observations:'',attempts:'',nextAction:'',pins:[],reviews:[],...(lab.workspace || {})});
const studySettings = state => ({module:'ad',lesson:'/active-directory/index',...(state.study || {})});
const studySafeHref = href => typeof href==='string' && /^\/(?!\/)[a-z0-9][a-z0-9/_-]*(?:#[^\s<>]*)?$/i.test(href);
const studyValidate = state => {
  const fail=()=>{throw Error('Invalid workspace data. Existing saved work has not been replaced.');};
  const strings=(o,keys)=>o && keys.every(k=>typeof o[k]==='string');
  if(state.study!==undefined && (!strings(state.study,['module','lesson']) || !studySafeHref(state.study.lesson)))fail();
  for(const lab of state.labs){
    if(lab.workspace===undefined)continue;
    const w=lab.workspace;
    if(!strings(w,['boxId','services','observations','attempts','nextAction']) || !Array.isArray(w.pins)||!Array.isArray(w.reviews))fail();
    const hrefs=new Set(),ids=new Set();
    for(const p of w.pins){if(!strings(p,['title','href'])||!studySafeHref(p.href)||hrefs.has(p.href))fail();hrefs.add(p.href);}
    for(const r of w.reviews){if(!strings(r,['id','technique','confidence','notes','updated'])||!r.id||ids.has(r.id)||!['comfortable','help','revisit'].includes(r.confidence))fail();ids.add(r.id);}
  }return state;
};
const studyOpenBox = (state,box) => {
  const found=state.labs.find(l=>studyNotebook(l).boxId===box.id) || state.labs.find(l=>!studyNotebook(l).boxId && l.values.name.trim().toLowerCase()===box.name.toLowerCase());
  if(found)return {...state,active:found.id,labs:state.labs.map(l=>l.id===found.id?{...l,workspace:{...studyNotebook(l),boxId:box.id}}:l)};
  const lab=newLab(studyId(),'prepare');lab.values.name=box.name;lab.workspace={...studyNotebook(lab),boxId:box.id};
  return {...state,active:lab.id,labs:[...state.labs,lab]};
};
const studyPin = (state,entry) => {
  if(!studySafeHref(entry.href))throw Error('This reference cannot be saved.');
  return {...state,labs:state.labs.map(l=>{if(l.id!==state.active)return l;const w=studyNotebook(l);return {...l,workspace:{...w,pins:w.pins.some(p=>p.href===entry.href)?w.pins:[...w.pins,{title:entry.trail||entry.title,href:entry.href}]}};})};
};
const studyMerge = (current,incoming) => {
  studyValidate(incoming);
  // Imported labs always get new identities. Neither local notes nor same-name labs are overwritten.
  const labs=incoming.labs.map(l=>({...l,id:studyId(),values:{...l.values,name:(l.values.name||'Untitled lab')+' (imported)'}}));
  return {...current,active:labs[incoming.labs.findIndex(l=>l.id===incoming.active)].id,labs:[...current.labs,...labs],study:current.study||incoming.study};
};
const studyMarkdown = lab => {
  const w=studyNotebook(lab),line=s=>s.replace(/[\r\n]/g,' ');
  const block=s=>{const f='`'.repeat(Math.max(3,...(s.match(/`+/g)||[]).map(t=>t.length+1)));return f+'text\n'+(s||'(not recorded)')+'\n'+f;};
  const lines=['# '+line(lab.values.name||'Untitled lab'),'','## Box notebook',''];
  for(const [k,label] of [['services','Discovered services'],['observations','Observations and evidence paths'],['attempts','Attempted approaches and results'],['nextAction','Next action']])lines.push('### '+label,'',block(w[k]),'');
  lines.push('## Saved references','',...w.pins.map(p=>'- '+line(p.title)+' — https://dashboard-aed21664.mintlify.site'+p.href),'','## Revision','');
  for(const r of w.reviews)lines.push('### '+line(r.technique),'',r.confidence+' · '+r.updated,'',block(r.notes),'');
  return lines.join('\n');
};

const practiceBlank = () => ({version:1, modules:[], guidedAD:false, progress:{}});
const practiceRecord = () => ({status:'not-started', help:'unrecorded', date:'', replayed:false, explained:false, writeup:false, notes:''});
const practiceReadiness = (box, state, goal='start') => {
  const required=goal==='finish'?box.finish:box.start;
  const missing=required.filter(id=>!state.modules.includes(id));
  const guided=state.guidedAD && missing.includes('ad');
  const blocked=missing.filter(id=>!(guided && id==='ad'));
  const extras=goal==='finish'?box.extraFinish:box.extraStart;
  return {missing, blocked, extras, kind:blocked.length?'missing':extras.length?'stretch':guided?'guided':'ready'};
};
const practiceParse = (raw, data) => {
  const value=JSON.parse(raw);
  if(!value || value.version!==1 || !Array.isArray(value.modules) || typeof value.guidedAD!=='boolean' || !value.progress || Array.isArray(value.progress) || typeof value.progress!=='object') throw Error('This is not a version 1 practice-library backup.');
  const known=new Set(data.modules.map(m=>m.id));
  if(value.modules.some(id=>!known.has(id))) throw Error('The backup contains unknown modules.');
  const result={version:1,modules:[...new Set(value.modules)],guidedAD:value.guidedAD,progress:{}};
  for(const [id,p] of Object.entries(value.progress)) {
    if(!data.boxes.some(b=>b.id===id)) throw Error('The backup contains an unknown box: '+id);
    if(!p || !['not-started','in-progress','foothold','completed'].includes(p.status) || !['unrecorded','independent','hint','walkthrough'].includes(p.help) || typeof p.notes!=='string' || p.notes.length>20000 || typeof p.date!=='string' || (p.date && (!/^\d{4}-\d{2}-\d{2}$/.test(p.date) || !Number.isFinite(Date.parse(p.date)) || new Date(p.date).toISOString().slice(0,10)!==p.date)) || ['replayed','explained','writeup'].some(k=>typeof p[k]!=='boolean')) throw Error('Invalid progress record for '+id+'. Nothing was imported.');
    result.progress[id]={status:p.status,help:p.help,date:p.date,replayed:p.replayed,explained:p.explained,writeup:p.writeup,notes:p.notes};
  }
  return result;
};
// Merge fills missing records. Existing records win, so an older backup cannot erase current work.
const practiceMerge = (current,incoming) => ({version:1,modules:[...new Set([...current.modules,...incoming.modules])],guidedAD:current.guidedAD||incoming.guidedAD,progress:{...incoming.progress,...current.progress}});
const practiceMarkdown = (state,data) => {
  const title=id=>data.modules.find(m=>m.id===id)?.name||id;
  const lines=['# HTB practice progress','','Self-recorded practice; not official HTB completion.','','## Modules I have studied','',...state.modules.map(id=>'- [x] '+title(id)),'', 'Current AD guided practice: '+(state.guidedAD?'included':'not included'),'', '## Box journal',''];
  for(const box of data.boxes){const p=state.progress[box.id];if(!p)continue;lines.push('### '+box.name,'','- Progress: '+p.status,'- Help used: '+p.help,'- Completion date: '+(p.date||'not recorded'),'- ['+(p.replayed?'x':' ')+'] Repeated without a guide','- ['+(p.explained?'x':' ')+'] Can explain the route','- ['+(p.writeup?'x':' ')+'] Own write-up saved','',p.notes||'No reflection recorded.','');}
  return lines.join('\n');
};


